{"path":"/root/solve.py","content":"#!/usr/bin/env python3
"""Compute home-infusion batch financial analysis artifacts."""

import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

ROOT = Path('/root')
CATALOG_PATH = ROOT / 'therapy_catalog.json'
BAG_COST_PATH = ROOT / 'bag_supply_cost.csv'
DELIVERY_PAYMENT_PATH = ROOT / 'delivery_payment.csv'
PATIENT_OVERRIDES_PATH = ROOT / 'patient_overrides.csv'
JSON_OUTPUT_PATH = ROOT / 'infusion_batch_analysis.json'
SUMMARY_OUTPUT_PATH = ROOT / 'infusion_batch_summary.md'

MODELS = {
    '7_day': {'deliveries_per_year': 52, 'days_per_delivery': 7},
    '14_day': {'deliveries_per_year': 26, 'days_per_delivery': 14},
}
THRESHOLD_USD = Decimal('15000')


def money(value):
    """Return a float rounded to exactly cents for JSON numeric output."""
    return float(Decimal(value).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))


def dec(value):
    return Decimal(str(value))


def read_csv_dicts(path):
    with path.open(newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))


def load_therapy_records(path):
    with path.open(encoding='utf-8') as f:
        raw = json.load(f)

    if isinstance(raw, list):
        return raw

    therapies = []
    for service_line in raw.get('service_lines', []):
        for therapy in service_line.get('therapies', []):
            therapy_copy = dict(therapy)
            therapy_copy.setdefault('service_line', service_line.get('service_line'))
            therapies.append(therapy_copy)
    return therapies


def main():
    all_therapies = load_therapy_records(CATALOG_PATH)
    in_scope = [t for t in all_therapies if t.get('include_in_review') is True]
    in_scope_by_code = {t['therapy_code']: t for t in in_scope}

    label_lookup = {}
    for therapy in in_scope:
        labels = [therapy.get('therapy_name')]
        labels.extend(therapy.get('aliases') or [])
        for label in labels:
            if label:
                label_lookup[label] = therapy

    payments_by_code = {}
    for row in read_csv_dicts(DELIVERY_PAYMENT_PATH):
        therapy = label_lookup.get(row['therapy_label'])
        if therapy is not None:
            payments_by_code[therapy['therapy_code']] = dec(row['payment_per_delivery_per_patient_usd'])

    approved_overrides = {}
    for row in read_csv_dicts(PATIENT_OVERRIDES_PATH):
        code = row['therapy_code']
        if row['status'] != 'approved' or code not in in_scope_by_code:
            continue
        revision = int(row['revision'])
        if code not in approved_overrides or revision > approved_overrides[code]['revision']:
            approved_overrides[code] = {
                'revision': revision,
                'active_patients': int(row['active_patients']),
            }

    bag_cost_by_size = {
        int(row['bag_size_ml']): dec(row['bag_supply_cost_usd'])
        for row in read_csv_dicts(BAG_COST_PATH)
    }

    therapies_out = []
    total_margin_7 = Decimal('0')
    total_margin_14 = Decimal('0')

    for therapy in sorted(in_scope, key=lambda t: t['therapy_code']):
        code = therapy['therapy_code']
        if code not in approved_overrides:
            raise ValueError(f'Missing approved patient override for in-scope therapy {code}')
        if code not in payments_by_code:
            raise ValueError(f'Missing delivery payment for in-scope therapy {code}')

        bag_size_ml = int(therapy['bag_size_ml'])
        if bag_size_ml not in bag_cost_by_size:
            raise ValueError(f'Missing bag supply cost for bag size {bag_size_ml} ml')

        active_patients = approved_overrides[code]['active_patients']
        active_patients_dec = Decimal(active_patients)
        drug_cost_per_1000 = dec(therapy['drug_cost_per_1000_mg_usd'])
        dose_mg_per_day = dec(therapy['dose_mg_per_day'])
        bag_supply_cost = bag_cost_by_size[bag_size_ml]
        payment = payments_by_code[code]

        model_results = {}
        for model_name, constants in MODELS.items():
            deliveries = Decimal(constants['deliveries_per_year'])
            days = Decimal(constants['days_per_delivery'])
            annual_drug_cost = drug_cost_per_1000 * active_patients_dec * dose_mg_per_day * days * deliveries / Decimal('1000')
            annual_supply_cost = bag_supply_cost * active_patients_dec * deliveries
            annual_revenue = payment * active_patients_dec * deliveries
            annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost
            model_results[model_name] = {
                'annual_drug_cost_usd': money(annual_drug_cost),
                'annual_supply_cost_usd': money(annual_supply_cost),
                'annual_revenue_usd': money(annual_revenue),
                'annual_margin_usd': money(annual_margin),
                '_annual_margin_decimal': annual_margin,
            }

        margin_7 = model_results['7_day']['_annual_margin_decimal']
        margin_14 = model_results['14_day']['_annual_margin_decimal']
        total_margin_7 += margin_7
        total_margin_14 += margin_14
        margin_difference = margin_14 - margin_7

        therapies_out.append({
            'therapy_code': code,
            'therapy_name': therapy['therapy_name'],
            'active_patients': active_patients,
            'patient_override_revision': approved_overrides[code]['revision'],
            'bag_size_ml': bag_size_ml,
            'bag_supply_cost_usd': money(bag_supply_cost),
            'payment_per_delivery_per_patient_usd': money(payment),
            'drug_cost_per_1000_mg_usd': money(drug_cost_per_1000),
            'dose_mg_per_day': money(dose_mg_per_day),
            'annual_drug_cost_7_day_usd': model_results['7_day']['annual_drug_cost_usd'],
            'annual_supply_cost_7_day_usd': model_results['7_day']['annual_supply_cost_usd'],
            'annual_revenue_7_day_usd': model_results['7_day']['annual_revenue_usd'],
            'annual_margin_7_day_usd': model_results['7_day']['annual_margin_usd'],
            'annual_drug_cost_14_day_usd': model_results['14_day']['annual_drug_cost_usd'],
            'annual_supply_cost_14_day_usd': model_results['14_day']['annual_supply_cost_usd'],
            'annual_revenue_14_day_usd': model_results['14_day']['annual_revenue_usd'],
            'annual_margin_14_day_usd': model_results['14_day']['annual_margin_usd'],
            'annual_margin_difference_14_minus_7_usd': money(margin_difference),
        })

    total_difference = total_margin_14 - total_margin_7
    absolute_difference = abs(total_difference)
    decision = 'move_to_14_day' if absolute_difference < THRESHOLD_USD else 'keep_7_day'
    justification = (
        f"The absolute total annual margin difference is ${money(absolute_difference):,.2f}, "
        f"which is {'below' if absolute_difference < THRESHOLD_USD else 'at or above'} "
        f"the ${THRESHOLD_USD:,.2f} threshold."
    )

    output = {
        'assumptions': {
            'models': {
                '7_day': {'deliveries_per_year': 52, 'days_per_delivery': 7},
                '14_day': {'deliveries_per_year': 26, 'days_per_delivery': 14},
            },
            'decision_threshold_usd': money(THRESHOLD_USD),
            'currency_rounding': 'All currency values rounded to 2 decimal places.',
            'therapy_filter': 'Only therapy_catalog entries with include_in_review=true are included.',
            'patient_override_rule': 'Approved override with the highest revision is used for each in-scope therapy.',
        },
        'therapies': therapies_out,
        'totals': {
            'total_annual_margin_7_day_usd': money(total_margin_7),
            'total_annual_margin_14_day_usd': money(total_margin_14),
            'total_annual_margin_difference_14_minus_7_usd': money(total_difference),
            'absolute_total_margin_difference_usd': money(absolute_difference),
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    JSON_OUTPUT_PATH.write_text(json.dumps(output, indent=2) + '\n', encoding='utf-8')

    totals = output['totals']
    summary = (
        '# Infusion Batch Analysis Summary\n\n'
        f"Total 7-Day Annual Margin: ${totals['total_annual_margin_7_day_usd']:,.2f}\n"
        f"Total 14-Day Annual Margin: ${totals['total_annual_margin_14_day_usd']:,.2f}\n"
        f"Absolute Margin Difference: ${totals['absolute_total_margin_difference_usd']:,.2f}\n"
        f"Recommendation: {decision}\n"
    )
    SUMMARY_OUTPUT_PATH.write_text(summary, encoding='utf-8')


if __name__ == '__main__':
    main()
","cross_profile":false}

